const body = $json.body ?? $json;
const raw = body.vmid ?? body.ct ?? body.ct_number;
const vmid = Number(raw);
if (!Number.isInteger(vmid) || vmid < 100 || vmid > 999999) throw new Error('invalid_vmid');
const action = body.requested_action ?? 'reconcile';
if (!['inspect','reconcile','deploy','repair'].includes(action)) throw new Error('invalid_action');
const startPolicy = body.start_policy ?? 'approval_required';
if (!['never','approval_required'].includes(startPolicy)) throw new Error('invalid_start_policy');
return [{ json: { vmid, requested_action: action, start_policy: startPolicy, mode: 'continue_until_done', job_key: `ct:${vmid}:${action}`, correlation_id: `ct-${vmid}-${Date.now()}` } }];
